function initPortraitSlider(){
  const track=document.querySelector('#gallery .photoGrid');
  const cards=Array.from(track.children);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  let index=0, visible=false, timer, touchX=0;
  function schedule(){
    clearTimeout(timer);
    if(!reduced.matches && visible && !document.hidden &&
       !document.querySelector('dialog[open]') && !track.matches(':focus-within')){
      timer=setTimeout(()=>show(index+1),4000);
    }
  }
  function show(next){
    index=(next+cards.length)%cards.length;
    cards.forEach((card,i)=>{
      let slot=(i-index+cards.length)%cards.length;
      if(slot>cards.length/2)slot-=cards.length;
      card.dataset.slot=String(slot);
      card.tabIndex=slot===0?0:-1;
    });
    schedule();
  }
  track.classList.add('portraitStage');
  track.addEventListener('click',e=>{
    const card=e.target.closest('button');
    if(card && card!==cards[index]){
      e.stopPropagation();
      show(cards.indexOf(card));
    }
  },true);
  track.addEventListener('touchstart',e=>{touchX=e.touches[0].clientX},{passive:true});
  track.addEventListener('touchend',e=>{
    const dx=e.changedTouches[0].clientX-touchX;
    if(Math.abs(dx)>40)show(index+(dx<0?1:-1));
  },{passive:true});
  track.addEventListener('focusin',()=>clearTimeout(timer));
  track.addEventListener('focusout',()=>setTimeout(schedule,0));
  document.querySelector('#photoDialog').addEventListener('close',schedule);
  document.addEventListener('visibilitychange',schedule);
  new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;schedule()}).observe(track);
  reduced.addEventListener('change',schedule);
  show(0);
}
initPortraitSlider();

function initMobileExcerpts(){
  const groups=[
    {selector:'#about .aboutContent',id:'aboutMore'},
    {selector:'#tashang .intro > div',id:'tasMore'}
  ];
  for(const {selector,id} of groups){
    const container=document.querySelector(selector);
    const paragraphs=Array.from(container.children).filter(el=>el.tagName==='P');
    if(paragraphs.length<2)continue;
    const extra=document.createElement('div');
    extra.id=id;
    extra.className='mobileExcerpt';
    paragraphs[1].before(extra);
    paragraphs.slice(1).forEach(p=>extra.append(p));
    const toggle=document.createElement('button');
    toggle.type='button';
    toggle.className='excerptToggle';
    toggle.setAttribute('aria-controls',id);
    toggle.setAttribute('aria-expanded','false');
    extra.after(toggle);
    function refresh(){
      const expanded=extra.classList.contains('expanded');
      const fa=document.documentElement.lang==='fa';
      const label=expanded?(fa?'نمایش کمتر':'Show less'):(fa?'خواندن ادامهٔ متن':'Read more');
      toggle.textContent=expanded?(fa?'بستن':'Less'):'…';
      toggle.setAttribute('aria-label',label);
      toggle.title=label;
      toggle.setAttribute('aria-expanded',String(expanded));
    }
    toggle.addEventListener('click',()=>{
      extra.classList.toggle('expanded');
      refresh();
    });
    new MutationObserver(refresh).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
    refresh();
  }
}
initMobileExcerpts();

/* Faster-than-scroll background grid, without moving any page content. */
function initGridParallax(){
  const root=document.documentElement;
  const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
  let scheduled=false;
  function render(){
    scheduled=false;
    const scroll=window.scrollY || window.pageYOffset || 0;
    root.style.setProperty('--grid-page-offset', (-scroll*1.8).toFixed(2)+'px');
    root.style.setProperty('--grid-hero-offset', (-scroll*0.8).toFixed(2)+'px');
  }
  function onScroll(){
    if(scheduled || motionPreference.matches)return;
    scheduled=true;
    window.requestAnimationFrame(render);
  }
  function onPreferenceChange(){
    if(motionPreference.matches){
      root.style.removeProperty('--grid-page-offset');
      root.style.removeProperty('--grid-hero-offset');
    }else{
      onScroll();
    }
  }
  window.addEventListener('scroll',onScroll,{passive:true});
  motionPreference.addEventListener('change',onPreferenceChange);
  onPreferenceChange();
}
initGridParallax();
